mapper.select:
SELECT FROM spu WHERE deleted_at IS NULL
AND id IN #{id}
AND 1 = 0

mapper.update:
UPDATE spu SET deleted_at = NULL,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime}, version = version + 1
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at = #{et.deletedAt}
  AND version = #{MP_OPTLOCK_VERSION_ORIGINAL}

