mapper.select:
SELECT id FROM category WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id FOR UPDATE

SELECT b.id AS brand_id, b.name AS brand_name, c1.id AS category1_id, c2.id AS category2_id,
       c3.id AS category3_id, c3.name AS category_name, t.id AS template_id
FROM brand b
JOIN category c1 ON c1.id = #{value.category1Id} AND c1.parent_id IS NULL
JOIN category c2 ON c2.id = #{value.category2Id} AND c2.parent_id = c1.id
JOIN category c3 ON c3.id = #{value.category3Id} AND c3.parent_id = c2.id
JOIN template t ON t.id = c3.template_id AND t.id = #{value.templateId}
WHERE b.id = #{value.brandId} AND b.tenant_id = #{tenantId}
  AND c1.tenant_id = #{tenantId} AND c2.tenant_id = #{tenantId} AND c3.tenant_id = #{tenantId} AND t.tenant_id = #{tenantId}
  AND b.deleted_at IS NULL AND c1.deleted_at IS NULL AND c2.deleted_at IS NULL AND c3.deleted_at IS NULL AND t.deleted_at IS NULL
